require_once __DIR__.'/../config/auth.php'; require_admin(); $id=(int)($_GET['id']??0);
$s=db()->prepare('SELECT * FROM livros WHERE id=?');$s->execute([$id]);$l=$s->fetch();if(!$l)exit('Livro não encontrado.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$d=array_map('trim',$_POST);$cover=upload_cover($_FILES['capa']);$pdf=upload_pdf($_FILES['arquivo_pdf']);$newQty=(int)$d['quantidade'];$avail=max(0,(int)$l['quantidade_disponivel']+$newQty-(int)$l['quantidade']);$s=db()->prepare('UPDATE livros SET codigo_barras=?,isbn=?,titulo=?,autor=?,categoria=?,editora=?,ano_publicacao=?,quantidade=?,quantidade_disponivel=?,descricao=?,biografia_autor=?,capa=COALESCE(?,capa),arquivo_pdf=COALESCE(?,arquivo_pdf) WHERE id=?');$s->execute([$d['codigo_barras'],$d['isbn'],$d['titulo'],$d['autor'],$d['categoria'],$d['editora'],(int)$d['ano_publicacao'],$newQty,$avail,$d['descricao'],$d['biografia_autor'],$cover,$pdf,$id]);flash('success','Livro atualizado.');redirect('admin/livros.php');}catch(Throwable $e){$error=$e->getMessage();}}
$pageTitle='Editar livro';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';
?><form class="panel" method="post" enctype="multipart/form-data"><?php if(!empty($error)):?><div class="notice error"><?=e($error)?></div><?php endif;?><?=csrf_field()?><div class="form-grid"><?php foreach(['codigo_barras'=>'Código de barras','isbn'=>'ISBN','titulo'=>'Título','autor'=>'Autor','categoria'=>'Categoria','editora'=>'Editora','ano_publicacao'=>'Ano de publicação','quantidade'=>'Quantidade'] as $f=>$label):?><div class="form-group"><label><?=$label?></label><input <?=in_array($f,['ano_publicacao','quantidade'])?'type="number"':''?> name="<?=$f?>" value="<?=e((string)$l[$f])?>"></div><?php endforeach;?></div><div class="form-group"><label>Descrição</label><textarea name="descricao"><?=e($l['descricao'])?></textarea></div><div class="form-group"><label>Biografia do autor</label><textarea name="biografia_autor"><?=e($l['biografia_autor'])?></textarea></div><div class="form-group"><label>Nova capa (opcional)</label><input type="file" name="capa" accept="image/*"></div><div class="form-group"><label>Substituir PDF (opcional, até 20 MB)</label><input type="file" name="arquivo_pdf" accept="application/pdf,.pdf"></div><?php if($l['arquivo_pdf']):?><p class="notice success">Este livro possui PDF e aparece em “Ler livros digitais”.</p><?php else:?><p class="notice">Sem PDF, o livro aparece em “Livros da escola”.</p><?php endif;?><button class="btn">Salvar alterações</button></form><?php require __DIR__.'/../includes/dashboard-footer.php';?>
